#include <vector>
#include <array>
#include <cstddef>
#include <omp.h>

struct Point {
    double x, y;
};

/* Count the number of cartesian points in each quadrant. The vector points contains a list of `Point` objects.
   Store the counts in `bins`.
   Use OpenMP to count in parallel.
   Example:

   input: [{x=1.5, y=0.1}, {x=-3, y=1.1}, {x=5, y=9}, {x=1.5, y=-1}, {x=3, y=-7}, {x=0.1, y=2}]
   output: [3, 1, 0, 2]
*/
void countQuadrants(std::vector<Point> const& points, std::array<size_t, 4> &bins) {
    bins = {0, 0, 0, 0};

    const std::size_t n = points.size();

    #pragma omp parallel
    {
        std::array<size_t, 4> local_bins = {0, 0, 0, 0};

        #pragma omp for nowait
        for (std::size_t i = 0; i < n; ++i) {
            const Point& p = points[i];

            if (p.x > 0.0 && p.y > 0.0) {
                ++local_bins[0]; // Quadrant I
            } else if (p.x < 0.0 && p.y > 0.0) {
                ++local_bins[1]; // Quadrant II
            } else if (p.x < 0.0 && p.y < 0.0) {
                ++local_bins[2]; // Quadrant III
            } else if (p.x > 0.0 && p.y < 0.0) {
                ++local_bins[3]; // Quadrant IV
            }
            // Points on axes (x == 0 or y == 0) are not counted.
        }

        #pragma omp critical
        {
            bins[0] += local_bins[0];
            bins[1] += local_bins[1];
            bins[2] += local_bins[2];
            bins[3] += local_bins[3];
        }
    }
}
